#include <stdio.h>

int main(void)
{
    int capacity = 1;
    for (int size = 0; size < 5; size++) {
        if (size == capacity) {
            capacity *= 2;
        }
    }
    printf("%d\n", capacity);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int size = 2;
    int capacity = 8;
    if (capacity > 1 && size <= capacity / 4) {
        capacity /= 2;
    }
    printf("%d %d\n", size, capacity);
    return 0;
}

